r={'schema_version':'reverse-image-analysis-lane-report/v2','lane_id':lane['id'],'route_fingerprint':route['route_fingerprint'],'source_artifact':{'sha256':'cf1cd9cd11ccc5748e03f75e6d9c6b01943728d03651712c1d84f3f13a75874d','frame':'1085x608'},'execution':{'mode':'sequential-fallback','independent_context':False,'context_disclosure':'Same integrator context after previous lane reports.'},'status':'complete','reviewed_modules':[{'id':'core.visual-evidence','version':11},{'id':'core.fidelity-discipline','version':12},{'id':'medium.photographic-capture','version':13},{'id':'detail.low-quality-artifacts','version':4}],'findings':[],'topic_dispositions':[],'control_requirements':[],'omission_checks':[],'handoffs':[],'conflicts':[]}
for key,axis,obs,ev,atoms in [
 ('photography','surface','The medium reads as a photographic capture with continuous texture, coherent light, and depth-dependent detail.','Hair strands, rounded skin surfaces and progressively defocused street forms share coherent capture behavior.', [('medium','Photographic rendering retains naturally continuous surfaces rather than painted outlines or CG surfaces.',['person','background'],'medium')]),
 ('softness','sharpness','Foreground remains softly resolved while background is substantially more defocused.','The eye and earcup are readable but their edges are gentle; street figures lack facial detail.', [('foreground','The main face, hair and headphones stay softly resolved rather than razor sharp.',['person'],'focus-ceiling'),('background','The street and pedestrian figures remain heavily defocused with no readable lettering or faces.',['background'],'depth-focus-hierarchy')]),
 ('bloom','surface','Fine bright hair has diffuse blooming edges and the photo carries a subtle fine texture.','The brightest flyaway strands spread softly into surrounding tones; smooth areas retain faint small-scale texture.', [('bloom','A soft diffuse bloom survives around the brightest fine hair.',['hair-rim'],'optical-bloom')])]:
 fid=p+key; role='primary'
 r['findings'].append({'id':fid,'owner_key':'capture.'+key,'scale':'global','axis':axis,'observation':obs,'source_evidence':[ev],'confidence':'high','causal_origin':'processing','materiality':'material','proposed_role':role,'default_drift_risk':'high','confounders':['Exact camera, lens, sensor, film, filter and processing cannot be identified.'],'atomic_obligations':[{'id':fid+':'+a[0],'axis':axis,'visible_result':a[1],'result_direction':a[1],'subject_or_region_ids':a[2],'relation_kind':a[3],'source_evidence':[ev],'confidence':'high','causal_origin':'processing','attribution_status':'confounded','materiality':'material','proposed_role':role,'target_strength':'moderate','confounders':[]} for a in atoms]})
for topic,keys in [('medium-and-process',['photography']),('capture-fidelity-ceiling',['softness']),('production-aesthetic',['photography','softness','bloom']),('artifact-preservation',['softness','bloom'])]:r['topic_dispositions'].append({'topic':topic,'disposition':'analyzed','finding_ids':[p+k for k in keys]})
r['artifact_dispositions']={'haze':'material, handoff to Color/Tone veil ownership','highlight_bloom':'material, merge with Color/Tone highlight rolloff or a single generic surface owner','foreground_softness':'material','background_defocus':'material','JPEG_blocking':'not-material; file format alone does not establish conspicuous visual blocks','motion_smear':'not-material; no stable dominant directional smear observed','fine_grain':'uncertain; faint texture cannot establish film grain or sensor origin','retouching':'uncertain; optical softness prevents confident inference','cosmetics':'uncertain; dark upper lid is visible but exact makeup process is not identifiable','production_label':'omit; no era, film stock, named artist or fashion genre required'}
r['control_requirements']=[{'requirement':'Place photographic softness ceiling early. Preserve relative foreground/background resolution without reusing a general sharpness upgrade.'},{'requirement':'One owner for hair bloom; keep its luminous rolloff distinct from detailed hair geometry and backlight placement.'}]
