with open('output/events.jsonl','a') as f:
 f.write(json.dumps({'timestamp':datetime.datetime.now(datetime.timezone.utc).isoformat(),'event':'lane_frozen','lane':lane['id'],'bytes':path.stat().st_size,'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'mode':'sequential-fallback'})+'\n')
 f.write(json.dumps({'timestamp':datetime.datetime.now(datetime.timezone.utc).isoformat(),'event':'lane_wave_complete','actual_lane_count':5,'delegated_fresh_lanes':1,'sequential_fallback_lanes':4,'actual_lane_waves':1,'malformed_lane_retries':0,'lane_reroutes':0})+'\n')
